// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Read safe Chat activation state and fixed limits
	// (GET /api/v1/chat/capability)
	GetChatCapability(ctx context.Context, request GetChatCapabilityRequestObject) (GetChatCapabilityResponseObject, error)
	// Reauthorize and reopen one typed result reference
	// (GET /api/v1/chat/result-references/{reference_id})
	GetChatResultReference(ctx context.Context, request GetChatResultReferenceRequestObject) (GetChatResultReferenceResponseObject, error)
	// Reauthorize and page one assistant result into the open grid
	// (GET /api/v1/chat/result-references/{reference_id}/page)
	GetChatResultPage(ctx context.Context, request GetChatResultPageRequestObject) (GetChatResultPageResponseObject, error)
	// Compile one query reference into the open table
	// (GET /api/v1/chat/result-references/{reference_id}/recorte)
	GetChatTableRecorte(ctx context.Context, request GetChatTableRecorteRequestObject) (GetChatTableRecorteResponseObject, error)
	// Download the on-grid recorte as XLSX
	// (GET /api/v1/chat/result-references/{reference_id}/xlsx)
	ExportChatResultXlsx(ctx context.Context, request ExportChatResultXlsxRequestObject) (ExportChatResultXlsxResponseObject, error)
	// Inspect one owner-scoped run without provider payloads
	// (GET /api/v1/chat/runs/{run_id})
	GetChatRun(ctx context.Context, request GetChatRunRequestObject) (GetChatRunResponseObject, error)
	// Idempotently request cancellation for one owner-scoped run
	// (POST /api/v1/chat/runs/{run_id}/cancel)
	CancelChatRun(ctx context.Context, request CancelChatRunRequestObject) (CancelChatRunResponseObject, error)
	// Stream persisted owner-scoped run events in monotonic sequence order
	// (GET /api/v1/chat/runs/{run_id}/events)
	StreamChatRunEvents(ctx context.Context, request StreamChatRunEventsRequestObject) (StreamChatRunEventsResponseObject, error)
	// List the current user's unexpired private threads
	// (GET /api/v1/chat/threads)
	ListChatThreads(ctx context.Context, request ListChatThreadsRequestObject) (ListChatThreadsResponseObject, error)
	// Create one private thread with configured retention
	// (POST /api/v1/chat/threads)
	CreateChatThread(ctx context.Context, request CreateChatThreadRequestObject) (CreateChatThreadResponseObject, error)
	// Explicitly delete one private thread and its Chat-only content
	// (DELETE /api/v1/chat/threads/{thread_id})
	DeleteChatThread(ctx context.Context, request DeleteChatThreadRequestObject) (DeleteChatThreadResponseObject, error)
	// Read one owner-scoped private thread
	// (GET /api/v1/chat/threads/{thread_id})
	GetChatThread(ctx context.Context, request GetChatThreadRequestObject) (GetChatThreadResponseObject, error)
	// Rename one private thread with optimistic versioning
	// (PATCH /api/v1/chat/threads/{thread_id})
	RenameChatThread(ctx context.Context, request RenameChatThreadRequestObject) (RenameChatThreadResponseObject, error)
	// Select or clear the explicit owner-scoped follow-up context
	// (PUT /api/v1/chat/threads/{thread_id}/active-result)
	SetChatActiveResult(ctx context.Context, request SetChatActiveResultRequestObject) (SetChatActiveResultResponseObject, error)
	// Read private ordered message content for the owning user
	// (GET /api/v1/chat/threads/{thread_id}/messages)
	ListChatMessages(ctx context.Context, request ListChatMessagesRequestObject) (ListChatMessagesResponseObject, error)
	// Persist and launch one idempotent bounded turn
	// (POST /api/v1/chat/threads/{thread_id}/turns)
	StartChatTurn(ctx context.Context, request StartChatTurnRequestObject) (StartChatTurnResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

